<?php
namespace App\Http\Controllers;
use App\Models\Vehicle; use App\Models\VehicleMovement; use App\Models\User; use App\Notifications\VehicleDeparted; use App\Notifications\VehicleReturned; use Illuminate\Http\Request; use Illuminate\Support\Carbon; use Illuminate\Support\Facades\DB; use Illuminate\Support\Facades\Notification;
class MovementController extends Controller { public function create(){ $vehicles=Vehicle::where('active',true)->whereDoesntHave('movements',fn($q)=>$q->where('status','out'))->orderBy('number')->get(); return view('driver.departure',compact('vehicles')); } public function store(Request $r){$d=$r->validate(['vehicle_id'=>'required|exists:vehicles,id','destination'=>'required|string|max:255','purpose'=>'nullable|string|max:1000','notes'=>'nullable|string|max:2000']); $movement=DB::transaction(function() use($d,$r){$v=Vehicle::where('id',$d['vehicle_id'])->where('active',true)->lockForUpdate()->firstOrFail(); if(VehicleMovement::where('vehicle_id',$v->id)->where('status','out')->exists()) abort(422,'ئەم ئۆتۆمبێلە پێشتر دەرچووە.'); return VehicleMovement::create(array_merge($d,['user_id'=>$r->user()->id,'departure_time'=>now(),'status'=>'out']));}); Notification::send($this->admins(),new VehicleDeparted($movement)); return redirect()->route('driver.home')->with('success','دەرچوونی ئۆتۆمبێل تۆمارکرا.');} public function returnVehicle(Request $r,VehicleMovement $movement){ if(!$r->user()->isAdmin() && $movement->user_id!==$r->user()->id) abort(403); if($movement->status!=='out') return back()->with('error','ئەم گەشتە پێشتر داخراوە.'); $movement->update(['return_time'=>now(),'status'=>'returned']); Notification::send($this->admins(),new VehicleReturned($movement)); return back()->with('success','کاتی گەڕانەوە تۆمارکرا.'); } public function mine(Request $r){$movements=VehicleMovement::with('vehicle')->where('user_id',$r->user()->id)->latest('departure_time')->paginate(15); return view('driver.history',compact('movements'));} public function active(Request $r){$movement=VehicleMovement::with('vehicle')->where('user_id',$r->user()->id)->where('status','out')->latest()->first(); return view('driver.active',compact('movement'));} public function adminIndex(){ $movements=VehicleMovement::with(['vehicle','driver'])->latest('departure_time')->paginate(20); $notReturned=VehicleMovement::with(['vehicle','driver'])->where('status','out')->latest('departure_time')->get(); return view('admin.movements',compact('movements','notReturned')); } private function admins(){ return User::where('role','admin')->where('active',true)->get(); } }
